def generate_guide_matrix(distance_matrix: np.ndarray) -> np.ndarray:
    n = distance_matrix.shape[0]
    guide_matrix = np.zeros((n, n))
    for i in range(n):
        sorted_indices = np.argsort(distance_matrix[i])
        mean_critical_distance = np.mean(distance_matrix[i][sorted_indices[:min(3, n)]])
        for j in range(n):
            if i == j:
                guide_matrix[i, j] = 0
            else:
                penalty = (1.5 if j in sorted_indices[:2] else 1) 
                guide_matrix[i, j] = distance_matrix[i, j] * penalty
                normalized_distance = distance_matrix[i, j] / mean_critical_distance
                guide_matrix[i, j] *= normalized_distance
    return guide_matrix
